//! A whole rundown handed over at once, against upstream's own `parseRundown`
//! (plan 015, follow-up). `fixtures/import_cues.json` is generated by
//! scripts/upstream-oracle/gen-import_cues.ts.
//!
//! Here it goes through `PUT /data/rundowns/:id`, sent the way a rundown is
//! read back: each group lists its entries, and each entry names its group.

use ontime_core::api::{handle, ApiRequest, HttpMethod};
use ontime_core::project::Project;
use ontime_core::rundown::Rundown;
use serde::Deserialize;
use serde_json::{json, Value};

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct Case {
    name: String,
    rundown: Value,
    flat_order: Vec<String>,
    cues: serde_json::Map<String, Value>,
}

#[derive(Deserialize)]
struct Fixture {
    cases: Vec<Case>,
}

/// The rundown as a list in its flat order, groups with their entry lists.
fn entries_of(rundown: &Value) -> Vec<Value> {
    let entries = rundown["entries"].as_object().unwrap();
    let mut list = Vec::new();
    for id in rundown["order"]
        .as_array()
        .unwrap()
        .iter()
        .filter_map(Value::as_str)
    {
        let entry = &entries[id];
        list.push(entry.clone());
        for child in entry["entries"]
            .as_array()
            .into_iter()
            .flatten()
            .filter_map(Value::as_str)
        {
            list.push(entries[child].clone());
        }
    }
    list
}

#[test]
fn a_whole_rundown_keeps_and_numbers_cues_as_upstream() {
    let fixture: Fixture = serde_json::from_str(include_str!("fixtures/import_cues.json")).unwrap();
    let mut failures = Vec::new();

    for case in &fixture.cases {
        let mut project = Project::default();
        project
            .rundowns
            .insert("show".into(), Rundown::new("show", "Show"));
        let request = ApiRequest {
            method: HttpMethod::Put,
            path: "/data/rundowns/show".into(),
            body: json!({ "entries": entries_of(&case.rundown) }),
            token: None,
            master_token: None,
            room_is_new: false,
            member: None,
        };
        let response = handle(&mut project, &request, 0);
        if response.status != 200 {
            failures.push(format!("{}: refused with {}", case.name, response.status));
            continue;
        }
        let rundown = &project.rundowns["show"];
        if rundown.flat_order != case.flat_order {
            failures.push(format!(
                "{}: flat order, upstream {:?}, ours {:?}",
                case.name, case.flat_order, rundown.flat_order
            ));
        }
        for (id, want) in &case.cues {
            let got = rundown
                .get(id)
                .and_then(|e| e.get("cue"))
                .cloned()
                .unwrap_or(Value::Null);
            // upstream keeps no cue on a delay or a group, and an empty one on a milestone
            let kind = rundown
                .get(id)
                .and_then(|e| e["type"].as_str())
                .unwrap_or_default();
            if matches!(kind, "delay" | "group") {
                continue;
            }
            if got != *want && !(want == &json!("") && got.is_null()) {
                failures.push(format!(
                    "{}: {id}.cue, upstream {want}, ours {got}",
                    case.name
                ));
            }
        }
    }

    assert!(
        failures.is_empty(),
        "{} differences:\n{}",
        failures.len(),
        failures.join("\n")
    );
}
